export const PAPER_SIZE = 10;

function choice(index, prompt, correct, wrongs) {
  const options = [correct, ...wrongs];
  if (new Set(options).size !== 4) throw new Error(`Question needs 4 distinct options: ${prompt}`);
  const shift = (index * 3) % options.length;
  const ordered = options.slice(shift).concat(options.slice(0, shift));
  return { id: `q${index + 1}`, type: 'mcq', prompt, options: ordered, correctAnswer: correct, points: 10, starterCode: '', rubric: '', tests: [] };
}

function pack(url, rows) {
  if (rows.length < PAPER_SIZE * 2) throw new Error(`${url} needs ${PAPER_SIZE * 2} questions so a retry can be a different set.`);
  const questions = rows.map((row, index) => choice(index, row[0], row[1], row.slice(2)));
  if (new Set(questions.map(question => question.prompt)).size !== questions.length) throw new Error(`Duplicate prompt in ${url}`);
  return { url, questions };
}

const q = (prompt, correct, ...wrongs) => [prompt, correct, ...wrongs];

